using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Text;using System.Text.Json;using TownOfHost;
partial class Program {
const string Video="AbCdef12_-3";
static byte[] Proto(params byte[][] fields)=>fields.SelectMany(x=>x).ToArray();
static byte[] Var(ulong n){var b=new List<byte>();do{byte v=(byte)(n&127);n>>=7;b.Add((byte)(v|(n==0?0:128)));}while(n!=0);return b.ToArray();}
static byte[] Num(int f,ulong v)=>Proto(Var((ulong)f*8),Var(v));
static byte[] Bin(int f,byte[] v)=>Proto(Var((ulong)f*8+2),Var((ulong)v.Length),v);
static byte[] Str(int f,string s)=>Bin(f,Encoding.UTF8.GetBytes(s));
static byte[] Message(string id="m",string channel="channel",string name="名前",string text="日本語😀",int type=1,string time="2026-11-12T11:00:00Z")=>Proto(Str(101,id),Bin(3,Proto(Str(10101,channel),Str(103,name))),Bin(2,Proto(Num(1,(ulong)type),Str(301,channel),Str(4,time),Str(16,text),Bin(19,Str(1,text)))));
static byte[] Batch(params byte[][] messages)=>Proto(Str(100602,"resume-token"),Proto(messages.Select(x=>Bin(1007,x)).ToArray()));
static string LiveJson(string detail="\"activeLiveChatId\":\"chat-id\"")=>"{\"items\":[{\"id\":\""+Video+"\",\"liveStreamingDetails\":{"+detail+"}}]}";
static void Deny(YouTubeFailure why,Action action){try{action();throw new Exception("Expected "+why);}catch(YouTubeApiException e){Check(e.Reason==why,"Expected "+why+" got "+e.Reason);}}
static Task SourceRun(OfficialYouTubeChatSource s,List<YouTubeChatBatch> output=null,CancellationToken token=default)=>s.RunAsync(Video,b=>output?.Add(b),token);
static YouTubeCredential Credential(bool key=false)=>new("synthetic-credential",key,DateTimeOffset.UtcNow.AddHours(1));
sealed class ApiHandler:HttpMessageHandler {
 internal readonly Queue<HttpResponseMessage> Responses=new();internal List<(string Uri,string Auth,string Key,Version Version,HttpVersionPolicy Policy,byte[] Body)> Requests=new();
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){Requests.Add((r.RequestUri.AbsoluteUri,r.Headers.Authorization?.ToString()??"",r.Headers.TryGetValues("x-goog-api-key",out var k)?k.Single():"",r.Version,r.VersionPolicy,r.Content==null?Array.Empty<byte>():await r.Content.ReadAsByteArrayAsync(ct)));if(Responses.Count==0)throw new Exception("Unplanned mock HTTP request");return Responses.Dequeue();}
}
static HttpResponseMessage JsonReply(string json,HttpStatusCode code=HttpStatusCode.OK)=>new(code){Content=new StringContent(json)};
static HttpResponseMessage GrpcReply(byte[] payload,string status="0",Version version=null){var r=new HttpResponseMessage(HttpStatusCode.OK){Version=version??HttpVersion.Version20,Content=new ByteArrayContent(payload)};r.Content.Headers.ContentType=new("application/grpc");if(status!=null)r.TrailingHeaders.Add("grpc-status",status);return r;}
static (OfficialYouTubeChatSource source,ApiHandler handler) Api(bool key=false,params HttpResponseMessage[] responses){var h=new ApiHandler();foreach(var response in responses)h.Responses.Enqueue(response);return(new(new MemoryYouTubeCredentials(Credential(key)),new HttpClient(h)),h);}
static void RunOfficialApi(){
Test("official videos liveChatId",()=>Check(OfficialYouTubeJson.LiveChatId(LiveJson(),Video)=="chat-id"));
foreach(var item in new[]{("\"actualEndTime\":\"2026-11-12T00:00:00Z\"",YouTubeFailure.LiveEnded),("\"actualStartTime\":\"2026-11-12T00:00:00Z\"",YouTubeFailure.ChatUnavailable),("",YouTubeFailure.NotLive)})Test("video condition "+item.Item2,()=>Deny(item.Item2,()=>OfficialYouTubeJson.LiveChatId(LiveJson(item.Item1),Video)));
foreach(var json in new[]{"{}","not-json","{\"items\":null}"})Test("invalid videos response "+json.Length,()=>Deny(YouTubeFailure.InvalidResponse,()=>OfficialYouTubeJson.LiveChatId(json,Video)));
Test("missing video unavailable",()=>Deny(YouTubeFailure.NotFound,()=>OfficialYouTubeJson.LiveChatId("{\"items\":[]}",Video)));
foreach(var c in new[]{(401,"",YouTubeFailure.AuthenticationExpired),(403,"quotaExceeded",YouTubeFailure.QuotaExceeded),(403,"dailyLimitExceeded",YouTubeFailure.QuotaExceeded),(403,"liveChatEnded",YouTubeFailure.LiveEnded),(403,"liveChatDisabled",YouTubeFailure.ChatUnavailable),(403,"forbidden",YouTubeFailure.PermissionDenied),(429,"",YouTubeFailure.QuotaExceeded),(404,"",YouTubeFailure.NotFound),(503,"",YouTubeFailure.NetworkInterrupted)})Test("HTTP mapping "+c.Item1+c.Item2,()=>Check(OfficialYouTubeJson.Error((HttpStatusCode)c.Item1,"{\"error\":{\"errors\":[{\"reason\":\""+c.Item2+"\"}]}}" )==c.Item3));
Test("no credentials yields zero HTTP calls",()=>{var h=new ApiHandler();using var s=new OfficialYouTubeChatSource(new MissingYouTubeCredentials(),new HttpClient(h));Deny(YouTubeFailure.MissingCredentials,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==0);});
Test("expired token yields zero HTTP calls",()=>{var h=new ApiHandler();using var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(new("synthetic",false,DateTimeOffset.UtcNow.AddSeconds(-1))),new HttpClient(h));Deny(YouTubeFailure.AuthenticationExpired,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==0);});
Test("invalid video yields zero HTTP calls",()=>{var(s,h)=Api();using(s)Deny(YouTubeFailure.InvalidResponse,()=>s.RunAsync("bad",_=>{},default).GetAwaiter().GetResult());Check(h.Requests.Count==0);});
foreach(bool key in new[]{false,true})Test("official REST to HTTP2 stream with header credentials "+key,()=>{var(s,h)=Api(key,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(Batch(Message()))));var batches=new List<YouTubeChatBatch>();using(s)SourceRun(s,batches).GetAwaiter().GetResult();Check(batches.Single().Comments.Single().Text=="日本語😀");Check(h.Requests.Count==2&&h.Requests[0].Uri.StartsWith("https://www.googleapis.com/youtube/v3/videos?")&&h.Requests[1].Uri=="https://youtube.googleapis.com/youtube.api.v3.V3DataLiveChatMessageService/StreamList");Check(h.Requests.All(x=>!x.Uri.Contains("synthetic")&&(key?x.Key=="synthetic-credential"&&x.Auth=="":x.Auth=="Bearer synthetic-credential"&&x.Key=="")));Check(h.Requests[1].Version==HttpVersion.Version20&&h.Requests[1].Policy==HttpVersionPolicy.RequestVersionExact);});
Test("resume token reused on bounded reconnect",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(Batch(Message())),"14"),JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),"14"));using(s){Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());}Check(Encoding.UTF8.GetString(h.Requests[3].Body).Contains("resume-token"));});
foreach(var code in new[]{(16,YouTubeFailure.AuthenticationExpired),(7,YouTubeFailure.PermissionDenied),(8,YouTubeFailure.QuotaExceeded),(9,YouTubeFailure.ChatUnavailable),(5,YouTubeFailure.NotFound),(14,YouTubeFailure.NetworkInterrupted),(3,YouTubeFailure.InvalidResponse)})Test("grpc status "+code.Item1,()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),code.Item1.ToString()));using(s)Deny(code.Item2,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==2);});
Test("protobuf gRPC media type accepted",()=>{var response=GrpcReply(Array.Empty<byte>(),"14");response.Content.Headers.ContentType=new("application/grpc+proto");var(s,h)=Api(false,JsonReply(LiveJson()),response);using(s)Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("HTTP1 downgrade rejected",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),version:HttpVersion.Version11));using(s)Deny(YouTubeFailure.TransportUnsupported,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("missing grpc trailers fail closed",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),null));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("trailers-only gRPC errors are recognized",()=>{var response=GrpcReply(Array.Empty<byte>(),null);response.Headers.Add("grpc-status","16");var(s,h)=Api(false,JsonReply(LiveJson()),response);using(s)Deny(YouTubeFailure.AuthenticationExpired,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("trailers-only successful end is reconnectable",()=>{var response=GrpcReply(Array.Empty<byte>(),null);response.Headers.Add("grpc-status","0");var(s,h)=Api(false,JsonReply(LiveJson()),response);using(s)SourceRun(s).GetAwaiter().GetResult();});
Test("chat end event stops stream",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(Batch(Message(type:4)))));using(s)Deny(YouTubeFailure.LiveEnded,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("video failure does not fall back to another endpoint",()=>{var(s,h)=Api(false,JsonReply("{}",HttpStatusCode.Forbidden));using(s)Deny(YouTubeFailure.PermissionDenied,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==1);});
Test("oversized videos body rejected",()=>{var(s,h)=Api(false,JsonReply(new string('x',2*1024*1024+1)));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("gRPC request matches independent protobuf fixture",()=>{var expected=Proto(Str(1,"chat"),Str(2,"ja"),Str(99,"resume"),Str(100,"id"),Str(100,"snippet"),Str(100,"authorDetails"));Check(expected.SequenceEqual(YouTubeGrpcProtocol.Request("chat","resume")));});
foreach(string text in new[]{"日本語😀","English","<b>unsafe</b>"})Test("official message text decoded "+text,()=>{var c=YouTubeGrpcProtocol.Response(Batch(Message(text:text))).Comments.Single();Check(c.Text==StreamSafety.Plain(text)&&c.Name=="名前"&&c.Channel=="channel"&&c.PublishedAt.HasValue);});
Test("text bounded without splitting emoji",()=>Check(YouTubeGrpcProtocol.Response(Batch(Message(text:new string('x',2047)+"😀"))).Comments.Single().Text.EndsWith("😀")));
foreach(int type in new[]{0,2,3,5,7,10,15,16,17,18,19,20,21,999})Test("system/event is not participation command "+type,()=>Check(YouTubeGrpcProtocol.Response(Batch(Message(type:type))).Comments.Count==0));
foreach(var bad in new[]{new byte[]{0},new byte[]{10,255},new byte[]{11},Enumerable.Repeat((byte)255,11).ToArray(),Bin(2,new byte[]{255}),Bin(1007,Str(101,new string('x',257))),Bin(1007,Bin(3,Bin(103,new byte[]{255})))})Test("malformed protobuf rejected "+Convert.ToHexString(bad.AsSpan(0,Math.Min(bad.Length,6))),()=>Deny(YouTubeFailure.InvalidResponse,()=>YouTubeGrpcProtocol.Response(bad)));
Test("unknown protobuf field safely skipped",()=>Check(YouTubeGrpcProtocol.Response(Proto(Num(500,12),Batch(Message()))).Comments.Count==1));
Test("empty protobuf response valid",()=>Check(YouTubeGrpcProtocol.Response(Array.Empty<byte>()).Comments.Count==0));
Test("offline timestamp ends response",()=>Check(YouTubeGrpcProtocol.Response(Str(2,"2026-11-12T00:00:00Z")).Ended));
Test("compressed gRPC frame rejected",()=>Deny(YouTubeFailure.TransportUnsupported,()=>YouTubeGrpcProtocol.ReadFrame(new MemoryStream(new byte[]{1,0,0,0,0}),default).GetAwaiter().GetResult()));
foreach(var data in new[]{new byte[]{0},new byte[]{0,0,0,0,2,1},new byte[]{0,127,255,255,255}})Test("truncated or oversized gRPC frame rejected "+data.Length,()=>Deny(YouTubeFailure.InvalidResponse,()=>YouTubeGrpcProtocol.ReadFrame(new MemoryStream(data),default).GetAwaiter().GetResult()));
Test("cancelled reads stop without network",()=>{using var c=new CancellationTokenSource();c.Cancel();bool cancelled=false;try{YouTubeGrpcProtocol.ReadFrame(new FragmentStream(new byte[]{0,0,0,0,0}),c.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}Check(cancelled);});
foreach(var field in new[]{Num(1007,1),Bin(1007,Num(2,1)),Bin(1007,Num(3,1)),Bin(1007,Bin(2,Num(1,ulong.MaxValue)))})Test("wrong message wire or enum range rejected "+field.Length,()=>Deny(YouTubeFailure.InvalidResponse,()=>YouTubeGrpcProtocol.Response(field)));
Test("invalid root JSON object fails closed",()=>Deny(YouTubeFailure.InvalidResponse,()=>OfficialYouTubeJson.LiveChatId("[]",Video)));
Test("cancelled non-cooperating stream read is bounded",()=>{using var c=new CancellationTokenSource(30);using var input=new NeverReadStream();bool cancelled=false;try{YouTubeGrpcProtocol.ReadFrame(input,c.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}Check(cancelled);});
Test("quiet stream rotates normally without an idle-chat error",()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply(LiveJson()));var response=GrpcReply(Array.Empty<byte>());response.Content=new StreamContent(new NeverReadStream());response.Content.Headers.ContentType=new("application/grpc");h.Responses.Enqueue(response);using var source=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h),TimeSpan.FromMilliseconds(80));SourceRun(source).GetAwaiter().GetResult();Check(h.Requests.Count==2);});
Test("frame bound enforced on writes",()=>Deny(YouTubeFailure.InvalidResponse,()=>YouTubeGrpcProtocol.Frame(new byte[YouTubeGrpcProtocol.MaxFrameBytes+1])));
Test("fragmented network reads reconstruct exactly",()=>{var data=Batch(Message());using var stream=new FragmentStream(YouTubeGrpcProtocol.Frame(data));Check(YouTubeGrpcProtocol.ReadFrame(stream,default).GetAwaiter().GetResult().SequenceEqual(data));});
Test("credential ToString redacts values",()=>Check(!Credential().ToString().Contains("synthetic")));
foreach(var redirect in new[]{"https://127.0.0.1:12345/","http://localhost:12345/","http://0.0.0.0:12345/","http://127.0.0.1/","http://127.0.0.1:12345/?state=x"})Test("PKCE rejects unsafe redirect "+redirect,()=>{bool denied=false;try{new YouTubePkceSession("desktop-client",new Uri(redirect));}catch(ArgumentException){denied=true;}Check(denied);});
Test("PKCE uses readonly scope and S256",()=>{var p=new YouTubePkceSession("desktop-client",new Uri("http://127.0.0.1:12345/oauth"));string uri=p.AuthorizationUri.AbsoluteUri;Check(uri.StartsWith("https://accounts.google.com/o/oauth2/v2/auth?")&&uri.Contains("code_challenge_method=S256")&&Uri.UnescapeDataString(uri).Contains("scope="+YouTubePkceSession.Scope)&&!uri.Contains("code_verifier"));});
Test("PKCE state verifies callback and permits one exchange",()=>{var p=new YouTubePkceSession("desktop-client",new Uri("http://127.0.0.1:12345/oauth"));string state=p.AuthorizationUri.Query.TrimStart('?').Split('&').Single(x=>x.StartsWith("state=")).Substring(6);var callback=new Uri(p.Redirect+"?code=synthetic-code&state="+state);var form=p.Complete(callback);Check(form["grant_type"]=="authorization_code"&&form["code_verifier"].Length==43);Deny(YouTubeFailure.AuthenticationExpired,()=>p.Complete(callback));});
Test("PKCE wrong state is rejected",()=>{var p=new YouTubePkceSession("desktop-client",new Uri("http://127.0.0.1:12345/oauth"));Deny(YouTubeFailure.AuthenticationExpired,()=>p.Complete(new Uri(p.Redirect+"?code=x&state=wrong")));});
Test("OAuth null config makes zero HTTP calls",()=>{var h=new ApiHandler();using var oauth=new YouTubeDesktopOAuth(new HttpClient(h));Deny(YouTubeFailure.MissingCredentials,()=>oauth.ExchangeAsync(null,default).GetAwaiter().GetResult());Check(h.Requests.Count==0);});
foreach(bool valid in new[]{false,true})Test("OAuth scope validation "+valid,()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply(JsonSerializer.Serialize(new{access_token="synthetic-token",refresh_token="synthetic-refresh",token_type="Bearer",expires_in=3600,scope=valid?YouTubePkceSession.Scope:"https://www.googleapis.com/auth/youtube.force-ssl"})));using var oauth=new YouTubeDesktopOAuth(new HttpClient(h));var form=new Dictionary<string,string>{{"client_id","desktop-client"},{"grant_type","authorization_code"},{"code","code"}};if(valid){var result=oauth.ExchangeAsync(form,default).GetAwaiter().GetResult();Check(result.Access.Valid&&!result.ToString().Contains("synthetic"));}else Deny(YouTubeFailure.AuthenticationExpired,()=>oauth.ExchangeAsync(form,default).GetAwaiter().GetResult());Check(h.Requests.Single().Uri=="https://oauth2.googleapis.com/token");});
Test("OAuth revoke uses official POST body without leaking token into URL",()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply("{}"));using var oauth=new YouTubeDesktopOAuth(new HttpClient(h));oauth.RevokeAsync("synthetic-revoke-token",default).GetAwaiter().GetResult();var request=h.Requests.Single();Check(request.Uri=="https://oauth2.googleapis.com/revoke"&&!request.Uri.Contains("synthetic")&&request.Auth==""&&Encoding.UTF8.GetString(request.Body)=="token=synthetic-revoke-token");});
foreach(var code in new[]{(429,YouTubeFailure.QuotaExceeded),(503,YouTubeFailure.NetworkInterrupted)})Test("OAuth temporary HTTP failure "+code.Item1,()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply("{}",(HttpStatusCode)code.Item1));using var oauth=new YouTubeDesktopOAuth(new HttpClient(h));Deny(code.Item2,()=>oauth.ExchangeAsync(new Dictionary<string,string>{{"client_id","desktop-client"},{"grant_type","refresh_token"},{"refresh_token","synthetic"}},default).GetAwaiter().GetResult());Check(h.Requests.Count==1);});
Test("revoked refresh stops and makes no fallback request",()=>{var h=new ApiHandler();h.Responses.Enqueue(JsonReply("{\"error\":\"invalid_grant\"}",HttpStatusCode.BadRequest));var tokens=new YouTubeOAuthTokens(new("expired",false,DateTimeOffset.UtcNow.AddMinutes(-1)),"synthetic-refresh");using var provider=new YouTubeOAuthMemoryProvider("client",tokens,new YouTubeDesktopOAuth(new HttpClient(h)));for(int n=0;n<2;n++)Deny(YouTubeFailure.AuthenticationExpired,()=>provider.GetAsync(default).GetAwaiter().GetResult());Check(h.Requests.Count==1);});
}
sealed class NeverReadStream:MemoryStream {public override ValueTask<int> ReadAsync(Memory<byte> bytes,CancellationToken ct=default)=>new(new TaskCompletionSource<int>().Task);}
sealed class FragmentStream:MemoryStream {internal FragmentStream(byte[] b):base(b){}public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken ct=default)=>base.ReadAsync(buffer[..Math.Min(buffer.Length,1)],ct);}
